-- Ledger initial PostgreSQL schema (proposal, not yet run in an environment).
-- IDs generated by application code as UUIDs. All timestamps represent instants.
-- PostgreSQL 15+ recommended. Apply in a transaction using a migration runner.
-- Secrets must be encrypted at the application boundary; SQL has no plaintext tokens.
BEGIN;

CREATE TABLE ledger_users (
  id uuid PRIMARY KEY,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE connected_mailboxes (
  id uuid PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES ledger_users(id) ON DELETE CASCADE,
  provider text NOT NULL CHECK (provider = 'GMAIL'),
  provider_subject text NOT NULL,
  address text NOT NULL,
  encrypted_refresh_token bytea NOT NULL,
  token_key_version integer NOT NULL DEFAULT 1,
  history_cursor text,
  sync_state text NOT NULL DEFAULT 'INITIALIZING'
    CHECK (sync_state IN ('INITIALIZING','HEALTHY','DEGRADED','RESYNC_REQUIRED','DISCONNECTED')),
  backfill_start timestamptz,
  backfill_end timestamptz,
  backfill_complete boolean NOT NULL DEFAULT false,
  last_success_at timestamptz,
  disconnected_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (user_id, provider, provider_subject),
  UNIQUE (id, user_id)
);

CREATE TABLE companies (
  id uuid PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES ledger_users(id) ON DELETE CASCADE,
  canonical_name text NOT NULL,
  normalized_domain text,
  UNIQUE (id, user_id)
);

CREATE TABLE job_openings (
  id uuid PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES ledger_users(id) ON DELETE CASCADE,
  company_id uuid NOT NULL,
  title text NOT NULL,
  location text,
  ats_provider text,
  ats_tenant text,
  requisition_id text,
  canonical_url text,
  listing_state text NOT NULL DEFAULT 'UNKNOWN'
    CHECK (listing_state IN ('UNKNOWN','OBSERVED_OPEN','OBSERVED_CLOSED')),
  listing_checked_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (company_id, user_id) REFERENCES companies(id, user_id),
  UNIQUE (id, user_id)
);
-- Do not auto-merge on title; ATS identity is only unique inside provider+tenant.
CREATE UNIQUE INDEX unique_opening_ats_key ON job_openings
  (user_id, ats_provider, ats_tenant, requisition_id)
  WHERE ats_provider IS NOT NULL AND ats_tenant IS NOT NULL AND requisition_id IS NOT NULL;

CREATE TABLE application_attempts (
  id uuid PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES ledger_users(id) ON DELETE CASCADE,
  job_opening_id uuid NOT NULL,
  applicant_email_snapshot text,
  phone_ciphertext bytea,
  phone_lookup_key text, -- keyed HMAC, NOT SHA(phone)
  external_application_id text,
  submitted_at timestamptz,
  stage text NOT NULL DEFAULT 'UNKNOWN'
    CHECK (stage IN ('UNKNOWN','APPLIED','ASSESSMENT','INTERVIEW')),
  outcome text NOT NULL DEFAULT 'PENDING'
    CHECK (outcome IN ('PENDING','REJECTED','OFFERED','WITHDRAWN')),
  monitoring_mode text NOT NULL DEFAULT 'FORWARD_OR_MANUAL'
    CHECK (monitoring_mode IN ('CONTINUOUS','FORWARD_OR_MANUAL','DISCONNECTED')),
  created_at timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (job_opening_id, user_id) REFERENCES job_openings(id, user_id),
  UNIQUE (id, user_id)
);
CREATE INDEX idx_attempts_opening ON application_attempts (user_id, job_opening_id);
-- Explicitly NO unique(email, opening), unique(phone, opening) or unique(opening).

CREATE TABLE source_artifacts (
  id uuid PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES ledger_users(id) ON DELETE CASCADE,
  source_kind text NOT NULL
    CHECK (source_kind IN ('GMAIL','FORWARDED_EML','MANUAL')),
  mailbox_id uuid,
  provider_message_id text,
  original_rfc_message_id text,
  source_fingerprint text NOT NULL,
  source_observed_at timestamptz NOT NULL DEFAULT now(),
  original_message_at timestamptz,
  body_access_decision text
    CHECK (body_access_decision IN ('NOT_FETCHED','FETCHED_CANDIDATE','SKIPPED_SENSITIVE','MANUAL_IMPORT')),
  extractor_version text,
  FOREIGN KEY (mailbox_id, user_id) REFERENCES connected_mailboxes(id, user_id),
  UNIQUE (id, user_id),
  UNIQUE (user_id, source_kind, source_fingerprint),
  CHECK (source_kind <> 'GMAIL' OR (mailbox_id IS NOT NULL AND provider_message_id IS NOT NULL))
);
CREATE UNIQUE INDEX idx_gmail_message_in_mailbox
  ON source_artifacts (mailbox_id, provider_message_id)
  WHERE source_kind = 'GMAIL';

CREATE TABLE application_events (
  id uuid PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES ledger_users(id) ON DELETE CASCADE,
  attempt_id uuid NOT NULL,
  event_kind text NOT NULL CHECK (event_kind IN (
    'SUBMITTED','CONFIRMATION_RECEIVED','ASSESSMENT_INVITED',
    'INTERVIEW_INVITED','INTERVIEW_SCHEDULED','REJECTION_RECEIVED',
    'OFFER_RECEIVED','WITHDRAWN','MANUAL_CORRECTION'
  )),
  occurred_at timestamptz NOT NULL,
  observed_at timestamptz NOT NULL DEFAULT now(),
  review_state text NOT NULL CHECK (review_state IN ('PROPOSED','ACCEPTED','REJECTED','SUPERSEDED')),
  source_type text NOT NULL CHECK (source_type IN ('GMAIL','FORWARDED_EML','MANUAL')),
  correction_stage text CHECK (correction_stage IN ('UNKNOWN','APPLIED','ASSESSMENT','INTERVIEW')),
  correction_outcome text CHECK (correction_outcome IN ('PENDING','REJECTED','OFFERED','WITHDRAWN')),
  dedupe_key text NOT NULL,
  FOREIGN KEY (attempt_id, user_id) REFERENCES application_attempts(id, user_id),
  UNIQUE (id, user_id),
  UNIQUE (user_id, dedupe_key),
  CHECK (event_kind <> 'MANUAL_CORRECTION' OR
    (correction_stage IS NOT NULL AND correction_outcome IS NOT NULL))
);
CREATE INDEX idx_events_attempt_time ON application_events (user_id, attempt_id, occurred_at);

CREATE TABLE event_evidence (
  user_id uuid NOT NULL REFERENCES ledger_users(id) ON DELETE CASCADE,
  event_id uuid NOT NULL,
  artifact_id uuid NOT NULL,
  -- no raw email HTML, credentials, signed links or OTP values.
  evidence_kind text NOT NULL,
  PRIMARY KEY (user_id, event_id, artifact_id),
  FOREIGN KEY (event_id, user_id) REFERENCES application_events(id, user_id),
  FOREIGN KEY (artifact_id, user_id) REFERENCES source_artifacts(id, user_id)
);

CREATE TABLE review_items (
  id uuid PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES ledger_users(id) ON DELETE CASCADE,
  source_artifact_id uuid,
  reason_code text NOT NULL,
  -- internal identifiers only; never store raw email payloads in this JSON.
  candidate_attempt_ids uuid[] NOT NULL DEFAULT '{}',
  state text NOT NULL DEFAULT 'OPEN' CHECK (state IN ('OPEN','RESOLVED','DISMISSED')),
  created_at timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (source_artifact_id, user_id) REFERENCES source_artifacts(id, user_id)
);

CREATE TABLE sync_runs (
  id uuid PRIMARY KEY,
  mailbox_id uuid NOT NULL REFERENCES connected_mailboxes(id) ON DELETE CASCADE,
  kind text NOT NULL CHECK (kind IN ('BACKFILL','INCREMENTAL','RESYNC')),
  window_start timestamptz,
  window_end timestamptz,
  cursor_before text,
  cursor_after text,
  started_at timestamptz NOT NULL DEFAULT now(),
  finished_at timestamptz,
  state text NOT NULL DEFAULT 'RUNNING' CHECK (state IN ('RUNNING','COMPLETED','FAILED')),
  safe_error_code text
);

COMMIT;
